Here is the commit message:
media: amphion: Fix VPU core alias name

Starting with commit f6038de293f2 ("arm64: dts: imx8qm: Fix VPU core
alias name") the alias for VPU cores uses dashes instead of underscores.
Adjust the alias stem accordingly. Fixes the errors:
amphion-vpu-core 2d040000.vpu-core: can't get vpu core id
amphion-vpu-core 2d050000.vpu-core: can't get vpu core id

Fixes: f6038de293f2 ("arm64: dts: imx8qm: Fix VPU core alias name")
Signed-off-by: Alexander Stein <alexander.stein@ew.tq-group.com>
Reviewed-by: Ming Qian <ming.qian@nxp.com>
Signed-off-by: Hans Verkuil <hverkuil-cisco@xs4all.nl>
Signed-off-by: Mauro Carvalho Chehab <mchehab@kernel.org>

Here is the root cause:
The bug was caused by a mismatch between the alias naming convention for VPU cores, which was changed in a previous commit to use dashes instead of underscores. The code was still referencing the old alias format, leading to errors when attempting to retrieve the VPU core ID.

Here is the patch:

 static int vpu_core_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct vpu_core *core;
 	struct vpu_dev *vpu = dev_get_drvdata(dev->parent);
 	struct vpu_shared_addr *iface;
 	u32 iface_data_size;
 	int ret;

 	dev_dbg(dev, "probe\n");
 	if (!vpu)
 		return -EINVAL;
 	core = devm_kzalloc(dev, sizeof(*core), GFP_KERNEL);
 	if (!core)
 		return -ENOMEM;

 	core->pdev = pdev;
 	core->dev = dev;
 	platform_set_drvdata(pdev, core);
 	core->vpu = vpu;
 	INIT_LIST_HEAD(&core->instances);
 	mutex_init(&core->lock);
 	mutex_init(&core->cmd_lock);
 	init_completion(&core->cmp);
 	init_waitqueue_head(&core->ack_wq);
 	vpu_core_set_state(core, VPU_CORE_DEINIT);

 	core->res = of_device_get_match_data(dev);
 	if (!core->res)
 		return -ENODEV;

 	core->type = core->res->type;
-	core->id = of_alias_get_id(dev->of_node, "vpu_core");
+	core->id = of_alias_get_id(dev->of_node, "vpu-core");
 	if (core->id < 0) {
 		dev_err(dev, "can't get vpu core id\n");
 		return core->id;
 	}
 	dev_info(core->dev, "[%d] = %s\n", core->id, vpu_core_type_desc(core->type));
 	ret = vpu_core_parse_dt(core, dev->of_node);
 	if (ret)
 		return ret;

 	core->base = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(core->base))
 		return PTR_ERR(core->base);

 	if (!vpu_iface_check_codec(core)) {
 		dev_err(core->dev, "is not supported\n");
 		return -EINVAL;
 	}

 	ret = vpu_mbox_init(core);
 	if (ret)
 		return ret;

 	iface = devm_kzalloc(dev, sizeof(*iface), GFP_KERNEL);
 	if (!iface)
 		return -ENOMEM;

 	iface_data_size = vpu_iface_get_data_size(core);
 	if (iface_data_size) {
 		iface->priv = devm_kzalloc(dev, iface_data_size, GFP_KERNEL);
 		if (!iface->priv)
 			return -ENOMEM;
 	}

 	ret = vpu_iface_init(core, iface, &core->rpc, core->fw.phys);
 	if (ret) {
 		dev_err(core->dev, "init iface fail, ret = %d\n", ret);
 		return ret;
 	}

 	vpu_iface_config_system(core, vpu->res->mreg_base, vpu->base);
 	vpu_iface_set_log_buf(core, &core->log);

 	pm_runtime_enable(dev);
 	ret = pm_runtime_resume_and_get(dev);
 	if (ret) {
 		pm_runtime_put_noidle(dev);
 		pm_runtime_set_suspended(dev);
 		goto err_runtime_disable;
 	}

 	ret = vpu_core_register(dev->parent, core);
 	if (ret)
 		goto err_core_register;
 	core->parent = dev->parent;

 	pm_runtime_put_sync(dev);
 	vpu_core_create_dbgfs_file(core);

 	return 0;

 err_core_register:
 	pm_runtime_put_sync(dev);
 err_runtime_disable:
 	pm_runtime_disable(dev);

 	return ret;
 }



